"""DORÉ DESIGN 2.0 direct-manipulation canvas adapter.

Selection stage: click/shift-click, marquee selection, selection bounds and
layout toolbar. The adapter emits validated document commands only.
"""
from html import escape
CSS='''<style id="dore2-canvas-style">[data-d2-node]{cursor:move;touch-action:none}[data-d2-node].d2-selected{outline:2px solid #8c6818!important;outline-offset:3px}.d2-handle{position:absolute;width:12px;height:12px;right:-8px;bottom:-8px;border:2px solid #fff;background:#8c6818;box-shadow:0 0 0 1px #5d4715;cursor:nwse-resize;z-index:9999}.d2-guide-x,.d2-guide-y{position:absolute;pointer-events:none;z-index:9998;background:rgba(140,104,24,.65);display:none}.d2-guide-x{top:0;bottom:0;width:1px}.d2-guide-y{left:0;right:0;height:1px}.d2-marquee,.d2-bounds{position:absolute;pointer-events:none;z-index:9997;border:1px solid #8c6818;background:rgba(206,189,116,.09);display:none}.d2-tools{position:absolute;z-index:10000;display:none;gap:2px;padding:4px;background:#252525;box-shadow:0 3px 12px #0003;white-space:nowrap}.d2-tools button{border:0;background:#fff;color:#252525;padding:5px 7px;font:10px ui-monospace,monospace;cursor:pointer}.d2-tools button:hover{background:#CEBD74}</style>'''
JS=r'''<script id="dore2-canvas-js">(()=>{const PAGE=document.body.dataset.d2Page,REV=()=>Number(document.body.dataset.d2Revision||0),canvas=document.querySelector('.canvas');if(!canvas||!PAGE)return;let selection=[],gesture=null,marquee=null;const gx=document.createElement('i'),gy=document.createElement('i'),mq=document.createElement('i'),bounds=document.createElement('i'),tools=document.createElement('div');gx.className='d2-guide-x';gy.className='d2-guide-y';mq.className='d2-marquee';bounds.className='d2-bounds';tools.className='d2-tools';tools.innerHTML='<button data-align="left">L</button><button data-align="center">C</button><button data-align="right">R</button><button data-align="top">T</button><button data-align="middle">M</button><button data-align="bottom">B</button><button data-dist="horizontal">H↔</button><button data-dist="vertical">V↕</button>';canvas.append(gx,gy,mq,bounds,tools);const num=(el,k)=>parseFloat(el.dataset[k]||0),scale=()=>canvas.getBoundingClientRect().width/canvas.offsetWidth||1,nodes=()=>[...canvas.querySelectorAll('[data-d2-node]')];function rect(el){return{x:num(el,'x'),y:num(el,'y'),w:num(el,'w')||el.offsetWidth,h:num(el,'h')||el.offsetHeight}}function union(els){const rs=els.map(rect),x=Math.min(...rs.map(r=>r.x)),y=Math.min(...rs.map(r=>r.y)),r=Math.max(...rs.map(v=>v.x+v.w)),b=Math.max(...rs.map(v=>v.y+v.h));return{x,y,w:r-x,h:b-y}}function paint(){nodes().forEach(n=>n.classList.toggle('d2-selected',selection.includes(n)));canvas.querySelectorAll('.d2-handle').forEach(x=>x.remove());if(selection.length===1){const h=document.createElement('b');h.className='d2-handle';selection[0].appendChild(h)}if(!selection.length){bounds.style.display=tools.style.display='none';return}const u=union(selection);Object.assign(bounds.style,{display:'block',left:u.x+'px',top:u.y+'px',width:u.w+'px',height:u.h+'px'});Object.assign(tools.style,{display:'flex',left:Math.max(0,u.x)+'px',top:Math.max(0,u.y-36)+'px'});parent.postMessage({type:'dore-selection',page_id:PAGE,ids:selection.map(x=>x.dataset.id)},'*');if(selection.length===1)parent.postMessage({type:'dore-select',page_id:PAGE,id:selection[0].dataset.id,field:'text',value:selection[0].innerText},'*')}function setSelection(list){selection=[...new Set(list)];paint()}function emit(command){parent.postMessage({type:'dore2-command',expected_revision:REV(),command},'*')}function guides(x,y,w,h){const cx=x+w/2,cy=y+h/2,CW=canvas.offsetWidth,CH=canvas.offsetHeight;gx.style.display=Math.abs(cx-CW/2)<7?'block':'none';gx.style.left=CW/2+'px';gy.style.display=Math.abs(cy-CH/2)<7?'block':'none';gy.style.top=CH/2+'px';return{x:Math.abs(cx-CW/2)<7?CW/2-w/2:x,y:Math.abs(cy-CH/2)<7?CH/2-h/2:y}}function hideGuides(){gx.style.display=gy.style.display='none'}tools.addEventListener('pointerdown',e=>e.stopPropagation());tools.addEventListener('click',e=>{const a=e.target.dataset.align,d=e.target.dataset.dist,ids=selection.map(n=>n.dataset.id);if(a&&ids.length>1)emit({op:'node.align',page_id:PAGE,ids,mode:a});if(d&&ids.length>2)emit({op:'node.distribute',page_id:PAGE,ids,axis:d})});canvas.addEventListener('pointerdown',e=>{if(e.target.closest('.d2-tools'))return;const el=e.target.closest('[data-d2-node]'),s=scale();if(!el){const cr=canvas.getBoundingClientRect(),x=(e.clientX-cr.left)/s,y=(e.clientY-cr.top)/s;marquee={id:e.pointerId,x,y,cx:x,cy:y,add:e.shiftKey};mq.style.display='block';Object.assign(mq.style,{left:x+'px',top:y+'px',width:'0px',height:'0px'});canvas.setPointerCapture(e.pointerId);if(!e.shiftKey)setSelection([]);return}e.preventDefault();if(e.shiftKey){setSelection(selection.includes(el)?selection.filter(x=>x!==el):selection.concat(el));return}if(!selection.includes(el))setSelection([el]);if(selection.length!==1)return;const resize=e.target.classList.contains('d2-handle'),r=rect(el);gesture={id:e.pointerId,el,resize,sx:e.clientX,sy:e.clientY,...r,s};el.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(marquee&&e.pointerId===marquee.id){const cr=canvas.getBoundingClientRect(),s=scale();marquee.cx=(e.clientX-cr.left)/s;marquee.cy=(e.clientY-cr.top)/s;const x=Math.min(marquee.x,marquee.cx),y=Math.min(marquee.y,marquee.cy),w=Math.abs(marquee.cx-marquee.x),h=Math.abs(marquee.cy-marquee.y);Object.assign(mq.style,{left:x+'px',top:y+'px',width:w+'px',height:h+'px'});return}if(!gesture||e.pointerId!==gesture.id)return;const dx=(e.clientX-gesture.sx)/gesture.s,dy=(e.clientY-gesture.sy)/gesture.s;if(gesture.resize){const w=Math.max(12,gesture.w+dx),h=Math.max(12,gesture.h+dy);gesture.el.style.width=w+'px';gesture.el.style.height=h+'px';gesture.p={w,h}}else{let x=gesture.x+dx,y=gesture.y+dy;({x,y}=guides(x,y,gesture.w,gesture.h));gesture.el.style.left=x+'px';gesture.el.style.top=y+'px';gesture.p={x,y}}paint()});canvas.addEventListener('pointerup',e=>{if(marquee&&e.pointerId===marquee.id){const x=Math.min(marquee.x,marquee.cx),y=Math.min(marquee.y,marquee.cy),r=Math.max(marquee.x,marquee.cx),b=Math.max(marquee.y,marquee.cy),hit=nodes().filter(n=>{const q=rect(n);return q.x<r&&q.x+q.w>x&&q.y<b&&q.y+q.h>y});setSelection(marquee.add?selection.concat(hit):hit);mq.style.display='none';marquee=null;return}if(!gesture||e.pointerId!==gesture.id)return;hideGuides();if(gesture.p)emit({op:'node.patch',page_id:PAGE,id:gesture.el.dataset.id,patch:gesture.p});gesture=null});parent.postMessage({type:'dore2-direct-ready',page_id:PAGE,revision:REV()},'*')})()</script>'''
def augment(html,page_id,revision):
    html=html.replace('</head>',CSS+'</head>',1).replace('<body ',f'<body data-d2-page="{escape(str(page_id))}" data-d2-revision="{int(revision)}" ',1)
    return html.replace('</body>',JS+'</body>',1)
